namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public List<int> Ratings { get; set; } = [];

    public double AverageRating =>
        Ratings.Count == 0 ? 0 : Math.Round(Ratings.Average(), 1);

    public int RatingCount => Ratings.Count;
}

public class RecipeSubmission
{
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
}

using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes =
        [
            new Recipe
            {
                Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
                Description = "A simple yet delicious traditional Italian pizza with fresh basil and mozzarella.",
                Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
                Steps = [
                    "Preheat oven to 475°F (245°C) with a pizza stone inside.",
                    "Stretch dough into a 12-inch round on a floured surface.",
                    "Spread crushed tomatoes evenly, leaving a 1-inch border.",
                    "Tear mozzarella into pieces and distribute over the sauce.",
                    "Bake for 10–12 minutes until crust is golden and cheese is bubbly.",
                    "Top with fresh basil leaves and a drizzle of olive oil."
                ],
                Ratings = [5, 4, 5, 4, 5]
            },
            new Recipe
            {
                Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
                Description = "Creamy Roman pasta made with eggs, cheese, pancetta, and black pepper.",
                Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Pecorino Romano", "Black pepper", "Salt"],
                Steps = [
                    "Cook spaghetti in salted boiling water until al dente.",
                    "Crisp pancetta in a skillet over medium heat.",
                    "Whisk eggs with grated Pecorino and black pepper in a bowl.",
                    "Drain pasta, reserving 1 cup of pasta water.",
                    "Toss hot pasta with pancetta, then remove from heat.",
                    "Quickly stir in the egg mixture, adding pasta water to create a creamy sauce."
                ],
                Ratings = [5, 5, 4]
            },
            new Recipe
            {
                Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
                Description = "Tender chicken pieces in a rich, spiced tomato-cream sauce.",
                Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Onion", "Garlic", "Ginger", "Cumin", "Turmeric"],
                Steps = [
                    "Marinate chicken in yogurt, garam masala, and turmeric for at least 1 hour.",
                    "Grill or broil chicken until charred and cooked through.",
                    "Sauté onion, garlic, and ginger in a large pan.",
                    "Add cumin, garam masala, and tomato sauce; simmer 15 minutes.",
                    "Stir in heavy cream and add the cooked chicken.",
                    "Simmer for 10 minutes and serve over basmati rice."
                ],
                Ratings = [5, 4, 5, 5]
            },
            new Recipe
            {
                Id = 4, Title = "Vegetable Pad Thai", Category = "Thai",
                Description = "A vibrant stir-fried noodle dish with crunchy vegetables and tangy sauce.",
                Ingredients = ["Rice noodles", "Tofu", "Bean sprouts", "Carrots", "Green onions", "Peanuts", "Tamarind paste", "Fish sauce", "Lime", "Eggs"],
                Steps = [
                    "Soak rice noodles in warm water for 30 minutes, then drain.",
                    "Mix tamarind paste, fish sauce, sugar, and lime juice for the sauce.",
                    "Press and cube tofu, then pan-fry until golden.",
                    "Scramble eggs in the same pan, then add noodles and sauce.",
                    "Toss in bean sprouts, carrots, and green onions.",
                    "Serve topped with crushed peanuts and lime wedges."
                ],
                Ratings = [4, 4, 5]
            },
            new Recipe
            {
                Id = 5, Title = "Beef Tacos", Category = "Mexican",
                Description = "Seasoned ground beef in warm tortillas with fresh toppings.",
                Ingredients = ["Ground beef", "Taco seasoning", "Corn tortillas", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Salsa"],
                Steps = [
                    "Brown ground beef in a skillet over medium-high heat.",
                    "Add taco seasoning and water; simmer until thickened.",
                    "Warm tortillas in a dry skillet or microwave.",
                    "Fill tortillas with seasoned beef.",
                    "Top with shredded lettuce, diced tomato, cheese, sour cream, and salsa."
                ],
                Ratings = [4, 3, 5, 4]
            },
            new Recipe
            {
                Id = 6, Title = "Chocolate Lava Cake", Category = "Desserts",
                Description = "Rich individual chocolate cakes with a molten center.",
                Ingredients = ["Dark chocolate", "Butter", "Eggs", "Sugar", "Flour", "Vanilla extract"],
                Steps = [
                    "Preheat oven to 425°F (220°C). Butter and flour four ramekins.",
                    "Melt chocolate and butter together in a double boiler.",
                    "Whisk eggs and sugar until thick and pale.",
                    "Fold the chocolate mixture into the eggs, then fold in flour.",
                    "Divide batter among ramekins and bake for 12–14 minutes.",
                    "Invert onto plates and serve immediately with powdered sugar."
                ],
                Ratings = [5, 5, 5, 4, 5]
            },
            new Recipe
            {
                Id = 7, Title = "Greek Salad", Category = "Mediterranean",
                Description = "A refreshing salad with crisp vegetables, olives, and feta cheese.",
                Ingredients = ["Cucumber", "Tomatoes", "Red onion", "Kalamata olives", "Feta cheese", "Olive oil", "Red wine vinegar", "Oregano"],
                Steps = [
                    "Chop cucumber, tomatoes, and red onion into bite-sized pieces.",
                    "Combine vegetables in a large bowl with olives.",
                    "Whisk olive oil, red wine vinegar, and oregano for the dressing.",
                    "Pour dressing over the salad and toss gently.",
                    "Top with crumbled feta cheese and serve."
                ],
                Ratings = [4, 4, 3]
            },
            new Recipe
            {
                Id = 8, Title = "Tom Yum Soup", Category = "Thai",
                Description = "A hot and sour Thai soup with shrimp, mushrooms, and aromatic herbs.",
                Ingredients = ["Shrimp", "Mushrooms", "Lemongrass", "Galangal", "Kaffir lime leaves", "Chili paste", "Fish sauce", "Lime juice", "Cilantro"],
                Steps = [
                    "Bring chicken broth to a boil with lemongrass, galangal, and lime leaves.",
                    "Add mushrooms and simmer for 5 minutes.",
                    "Stir in chili paste and fish sauce.",
                    "Add shrimp and cook until pink, about 3 minutes.",
                    "Remove from heat, add lime juice, and garnish with cilantro."
                ],
                Ratings = [5, 4]
            },
        ];
        _nextId = 9;
    }

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().Order().ToList();

    public IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
            recipe.Ratings.Add(stars);
    }

    public Recipe AddRecipe(RecipeSubmission submission)
    {
        var recipe = new Recipe
        {
            Id = _nextId++,
            Title = submission.Title.Trim(),
            Category = submission.Category.Trim(),
            Ingredients = submission.Ingredients
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList(),
            Steps = submission.Steps
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList(),
        };
        _recipes.Add(recipe);
        return recipe;
    }
}

