@rendermode InteractiveServer

<div class="star-rating d-inline-flex align-items-center">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= _hovered ? "hovered" : star <= _selected ? "selected" : "")"
              @onclick="() => SelectStar(star)"
              @onmouseover="() => _hovered = star"
              @onmouseout="() => _hovered = 0"
              role="button"
              title="Rate @star star(s)">
            ★
        </span>
    }
    @if (_submitted)
    {
        <span class="ms-2 text-success small">Thanks for rating!</span>
    }
</div>

<style>
    .star-rating .star {
        font-size: 1.8rem;
        color: #ccc;
        cursor: pointer;
        transition: color 0.15s, transform 0.15s;
        user-select: none;
        line-height: 1;
    }
    .star-rating .star:hover {
        transform: scale(1.2);
    }
    .star-rating .star.selected {
        color: #ffc107;
    }
    .star-rating .star.hovered {
        color: #ffdb4d;
    }
</style>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public EventCallback<int> OnRated { get; set; }

    private int _selected;
    private int _hovered;
    private bool _submitted;

    private async Task SelectStar(int star)
    {
        _selected = star;
        _submitted = true;
        await OnRated.InvokeAsync(star);
    }
}

@page "/"
@using RecipeCommunity.Services
@inject RecipeService RecipeService

<PageTitle>Recipe Community — Home</PageTitle>

<div class="text-center mb-4">
    <h1 class="display-4">🍳 Recipe Community</h1>
    <p class="lead text-muted">Discover, share, and rate delicious recipes from around the world.</p>
</div>

<div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4 mb-4">
    @foreach (var category in RecipeService.GetCategories())
    {
        <div class="col">
            <a href="/recipes/@Uri.EscapeDataString(category)" class="text-decoration-none">
                <div class="card h-100 shadow-sm border-0 category-card">
                    <div class="card-body text-center py-5">
                        <h3 class="card-title mb-2">@GetCategoryEmoji(category) @category</h3>
                        <p class="text-muted mb-0">
                            @RecipeService.GetByCategory(category).Count recipe(s)
                        </p>
                    </div>
                </div>
            </a>
        </div>
    }
</div>

<div class="text-center">
    <a href="/submit" class="btn btn-success btn-lg">📝 Submit a Recipe</a>
</div>

@code {
    private static string GetCategoryEmoji(string category) => category switch
    {
        "Italian" => "🇮🇹",
        "Indian" => "🇮🇳",
        "Thai" => "🇹🇭",
        "Mexican" => "🇲🇽",
        "Desserts" => "🍰",
        "Mediterranean" => "🫒",
        _ => "🍽️"
    };
}

@page "/recipes/{Category}"
@using RecipeCommunity.Services
@inject RecipeService RecipeService

<PageTitle>@Category Recipes — Recipe Community</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">@Category</li>
    </ol>
</nav>

<h2>@Category Recipes</h2>

@if (recipes.Count == 0)
{
    <div class="alert alert-info">No recipes found in this category.</div>
}
else
{
    <div class="row row-cols-1 row-cols-md-2 g-4">
        @foreach (var recipe in recipes)
        {
            <div class="col">
                <div class="card h-100 shadow-sm">
                    <div class="card-body">
                        <h5 class="card-title">
                            <a href="/recipe/@recipe.Id">@recipe.Title</a>
                        </h5>
                        <p class="card-text text-muted">@recipe.Description</p>
                        <div class="d-flex justify-content-between align-items-center">
                            <span class="text-warning">
                                @for (int i = 0; i < (int)Math.Round(recipe.AverageRating); i++) { <text>★</text> }
                                @for (int i = (int)Math.Round(recipe.AverageRating); i < 5; i++) { <text>☆</text> }
                            </span>
                            <small class="text-muted">@recipe.AverageRating / 5 (@recipe.RatingCount ratings)</small>
                        </div>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter] public string Category { get; set; } = string.Empty;

    private IReadOnlyList<RecipeCommunity.Models.Recipe> recipes = [];

    protected override void OnParametersSet()
    {
        recipes = RecipeService.GetByCategory(Uri.UnescapeDataString(Category));
    }
}

@page "/recipe/{Id:int}"
@using RecipeCommunity.Services
@using RecipeCommunity.Components.Shared
@inject RecipeService RecipeService

<PageTitle>@(recipe?.Title ?? "Recipe") — Recipe Community</PageTitle>

@if (recipe is null)
{
    <div class="alert alert-warning">Recipe not found.</div>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="/recipes/@Uri.EscapeDataString(recipe.Category)">@recipe.Category</a></li>
            <li class="breadcrumb-item active">@recipe.Title</li>
        </ol>
    </nav>

    <h2>@recipe.Title</h2>
    <p class="lead text-muted">@recipe.Description</p>

    <div class="mb-4 p-3 bg-light rounded">
        <strong>Average Rating:</strong>
        <span class="text-warning ms-1">
            @for (int i = 0; i < (int)Math.Round(recipe.AverageRating); i++) { <text>★</text> }
            @for (int i = (int)Math.Round(recipe.AverageRating); i < 5; i++) { <text>☆</text> }
        </span>
        <span class="text-muted ms-2">@recipe.AverageRating / 5 (@recipe.RatingCount ratings)</span>
    </div>

    <div class="row">
        <div class="col-md-4 mb-4">
            <div class="card">
                <div class="card-header"><h5 class="mb-0">🥘 Ingredients</h5></div>
                <ul class="list-group list-group-flush">
                    @foreach (var ingredient in recipe.Ingredients)
                    {
                        <li class="list-group-item">@ingredient</li>
                    }
                </ul>
            </div>
        </div>

        <div class="col-md-8 mb-4">
            <div class="card">
                <div class="card-header"><h5 class="mb-0">📋 Steps</h5></div>
                <div class="card-body">
                    <ol class="mb-0">
                        @foreach (var step in recipe.Steps)
                        {
                            <li class="mb-2">@step</li>
                        }
                    </ol>
                </div>
            </div>
        </div>
    </div>

    <div class="card mb-4">
        <div class="card-body">
            <h5>Rate this recipe:</h5>
            <StarRating RecipeId="recipe.Id" OnRated="HandleRating" />
        </div>
    </div>
}

@code {
    [Parameter] public int Id { get; set; }

    private RecipeCommunity.Models.Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetById(Id);
    }

    private void HandleRating(int stars)
    {
        RecipeService.AddRating(Id, stars);
        recipe = RecipeService.GetById(Id);
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeCommunity.Models
@using RecipeCommunity.Services
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe — Recipe Community</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">Submit Recipe</li>
    </ol>
</nav>

<h2>📝 Submit a Recipe</h2>
<p class="text-muted">Share your favorite recipe with the community!</p>

<div class="row">
    <div class="col-md-8">
        <EditForm Model="_submission" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
            <DataAnnotationsValidator />

            <div class="mb-3">
                <label for="title" class="form-label">Recipe Title</label>
                <InputText id="title" class="form-control" @bind-Value="_submission.Title"
                           placeholder="e.g. Grandma's Apple Pie" />
            </div>

            <div class="mb-3">
                <label for="category" class="form-label">Category</label>
                <InputSelect id="category" class="form-select" @bind-Value="_submission.Category">
                    <option value="">— Select a category —</option>
                    @foreach (var cat in RecipeService.GetCategories())
                    {
                        <option value="@cat">@cat</option>
                    }
                    <option value="Other">Other</option>
