                <div class="card h-100 shadow-sm border-0 category-card">
                    <div class="card-body text-center py-5">
                        <h3 class="card-title mb-2">@GetCategoryEmoji(category) @category</h3>
                        <p class="text-muted mb-0">
                            @RecipeService.GetByCategory(category).Count recipe(s)
                        </p>
                    </div>
                </div>
            </a>
        </div>
    }
</div>

<div class="text-center">
    <a href="/submit" class="btn btn-success btn-lg">📝 Submit a Recipe</a>
</div>

@code {
    private static string GetCategoryEmoji(string category) => category switch
    {
        "Italian" => "🇮🇹",
        "Indian" => "🇮🇳",
        "Thai" => "🇹🇭",
        "Mexican" => "🇲🇽",
        "Desserts" => "🍰",
        "Mediterranean" => "🫒",
        _ => "🍽️"
    };
}

@rendermode InteractiveServer

<div class="star-rating d-inline-flex align-items-center">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= _hovered ? "hovered" : star <= _selected ? "selected" : "")"
              @onclick="() => SelectStar(star)"
              @onmouseover="() => _hovered = star"
              @onmouseout="() => _hovered = 0"
              role="button"
              title="Rate @star star(s)">
            ★
        </span>
    }
    @if (_submitted)
    {
        <span class="ms-2 text-success small">Thanks for rating!</span>
    }
</div>

<style>
    .star-rating .star {
        font-size: 1.8rem;
        color: #ccc;
        cursor: pointer;
        transition: color 0.15s, transform 0.15s;
        user-select: none;
        line-height: 1;
    }
    .star-rating .star:hover {
        transform: scale(1.2);
    }
    .star-rating .star.selected {
        color: #ffc107;
    }
    .star-rating .star.hovered {
        color: #ffdb4d;
    }
</style>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public EventCallback<int> OnRated { get; set; }

    private int _selected;
    private int _hovered;
    private bool _submitted;

    private async Task SelectStar(int star)
    {
        _selected = star;
        _submitted = true;
        await OnRated.InvokeAsync(star);
    }
}

